services = list_services({})

# For each service, get error log pages and deploys in parallel
results = for svc in services {
    # Get first page of errors to see totals and timing
    logs = boundary retry 2 {
        return search_logs({ service: svc, level: "ERROR", page: 1 })
    } catch err {
        return fail("LOGS", err.message)
    }

    deploys = boundary retry 2 {
        return get_deploys({ service: svc })
    } catch err {
        return fail("DEPLOYS", err.message)
    }

    owner = boundary retry 2 {
        return get_service_owners({ service: svc })
    } catch err {
        return fail("OWNER", err.message)
    }

    # Sample more pages to understand distribution - get page counts
    # Fetch a few pages spread out to see error density over time
    total_pages = logs.total_pages

    # Get timestamps from first page and last pages if many
    more_pages = if total_pages > 1 {
        mid = number.floor(total_pages / 2) + 1
        last = total_pages
        pages_to_get = list.sort([mid, last])
        page_results = for p in pages_to_get {
            r = boundary retry 2 {
                return search_logs({ service: svc, level: "ERROR", page: p })
            } catch err {
                return fail("LOGS_P", err.message)
            }
            return { page: p, items: r.items, total_items: r.total_items }
        }
        return page_results
    } else {
        return []
    }

    first_ts = logs.items[0].ts if logs.items != [] else null
    last_items = more_pages[list.length(more_pages)-1].items if more_pages != [] else logs.items
    last_ts = last_items[list.length(last_items)-1].ts if last_items != [] else null

    return {
        service: svc,
        total_errors: logs.total_items,
        total_pages: total_pages,
        first_page_ts: for it in logs.items { return it.ts },
        more: more_pages,
        deploys: deploys,
        owner_email: owner.owner_email,
        first_ts: first_ts,
        last_ts: last_ts
    }
}

return results

